// This file will be updated step-by-step to include:
// 1. Mic & Cam toggle
// 2. Remote video tracks
// 3. Firebase chat integration

'use client'

import React, { useState, useRef, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import Picker from '@emoji-mart/react'
import data from '@emoji-mart/data'
import AgoraRTC, {
  IAgoraRTCClient,
  ILocalAudioTrack,
  ILocalVideoTrack,
  IRemoteVideoTrack,
  IRemoteAudioTrack,
  IRemoteUser
} from 'agora-rtc-sdk-ng'
import { initializeApp } from 'firebase/app'
import { getDatabase, ref, push, onChildAdded } from 'firebase/database'

const APP_ID = 'fd0e77a2c15f4c53af85276a8910ed8a'
const TOKEN = null
const CHANNEL = 'testChannel'

// Firebase config
const firebaseConfig = {
    apiKey: "AIzaSyBm03sG3SadkfPfQETb8kGHCGIL0S2i9Jw",
    authDomain: "pfe-project-f5f7b.firebaseapp.com",
    databaseURL: "https://pfe-project-f5f7b-default-rtdb.firebaseio.com",
    projectId: "pfe-project-f5f7b",
    storageBucket: "pfe-project-f5f7b.firebasestorage.app",
    messagingSenderId: "445560289586",
    appId: "1:445560289586:web:0a208f7a8f73273829bf2b",
    measurementId: "G-H2YEDWEXYQ"
  };
    if (typeof window !== 'undefined') {
    isSupported().then((yes) => {
      if (yes) {
        analytics = getAnalytics(app);
      }
    });
  }
  
  export { app, db, analytics };

export default function MeetingInterface() {
  const [activeTab, setActiveTab] = useState<'chat' | 'participants'>('chat')
  const [input, setInput] = useState('')
  const [showPicker, setShowPicker] = useState(false)
  const [direction, setDirection] = useState(1)
  const [messages, setMessages] = useState<string[]>([])

  const pickerRef = useRef<HTMLDivElement>(null)

  const [client] = useState<IAgoraRTCClient>(() =>
    AgoraRTC.createClient({ mode: 'rtc', codec: 'vp8' })
  )
  const [joined, setJoined] = useState(false)
  const [remoteUsers, setRemoteUsers] = useState<IRemoteUser[]>([])
  const localVideoRef = useRef<HTMLDivElement>(null)
  const remoteVideoRef = useRef<HTMLDivElement>(null)
  const audioTrack = useRef<ILocalAudioTrack | null>(null)
  const videoTrack = useRef<ILocalVideoTrack | null>(null)

  const [micOn, setMicOn] = useState(true)
  const [camOn, setCamOn] = useState(true)

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (pickerRef.current && !pickerRef.current.contains(e.target as Node)) {
        setShowPicker(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const addEmoji = (emoji: any) => {
    setInput((prev) => prev + emoji.native)
  }

  const handleTabChange = (tab: 'chat' | 'participants') => {
    setDirection(tab === 'chat' ? -1 : 1)
    setActiveTab(tab)
  }

  useEffect(() => {
    const joinChannel = async () => {
      if (joined) return
      try {
        await client.join(APP_ID, CHANNEL, TOKEN, null)
        const [micTrack, camTrack] = await AgoraRTC.createMicrophoneAndCameraTracks()
        audioTrack.current = micTrack
        videoTrack.current = camTrack

        if (localVideoRef.current) camTrack.play(localVideoRef.current)

        await client.publish([micTrack, camTrack])
        setJoined(true)
      } catch (err) {
        console.error('Join failed', err)
      }
    }

    joinChannel()

    client.on('user-published', async (user, mediaType) => {
      await client.subscribe(user, mediaType)
      setRemoteUsers((prev) => [...prev, user])
      if (mediaType === 'video' && remoteVideoRef.current) {
        user.videoTrack?.play(remoteVideoRef.current)
      }
    })

    client.on('user-unpublished', (user) => {
      setRemoteUsers((prev) => prev.filter((u) => u.uid !== user.uid))
    })

    return () => {
      client.leave()
      audioTrack.current?.close()
      videoTrack.current?.close()
    }
  }, [client, joined])

  useEffect(() => {
    onChildAdded(messagesRef, (data) => {
      setMessages((prev) => [...prev, data.val()])
    })
  }, [])

  const handleSend = () => {
    if (input.trim()) {
      push(messagesRef, input.trim())
      setInput('')
    }
  }

  const toggleMic = () => {
    if (audioTrack.current) {
      audioTrack.current.setEnabled(!micOn)
      setMicOn(!micOn)
    }
  }

  const toggleCam = () => {
    if (videoTrack.current) {
      videoTrack.current.setEnabled(!camOn)
      setCamOn(!camOn)
    }
  }

  return (
    <div className="flex h-screen">
      <div className="w-3/5 p-4">
        <h1 className="text-xl font-bold mb-2">Group Meeting</h1>

        <div className="grid grid-cols-2 gap-4 h-[60vh]">
          <div ref={localVideoRef} className="bg-black rounded-xl" />
          <div ref={remoteVideoRef} className="bg-gray-800 rounded-xl" />
        </div>

        <div className="mt-4 flex gap-2">
          <button onClick={toggleMic} className="bg-blue-500 px-4 py-2 text-white rounded">
            {micOn ? 'Mute Mic' : 'Unmute Mic'}
          </button>
          <button onClick={toggleCam} className="bg-purple-500 px-4 py-2 text-white rounded">
            {camOn ? 'Stop Cam' : 'Start Cam'}
          </button>
        </div>
      </div>

      <div className="w-2/5 p-4 bg-gray-100">
        <div className="flex mb-4">
          <button
            onClick={() => handleTabChange('chat')}
            className={`w-1/2 ${activeTab === 'chat' ? 'bg-black text-white' : ''}`}
          >
            Chat
          </button>
          <button
            onClick={() => handleTabChange('participants')}
            className={`w-1/2 ${activeTab === 'participants' ? 'bg-black text-white' : ''}`}
          >
            Participants
          </button>
        </div>

        <div className="relative h-[60vh] overflow-y-auto bg-white p-4 rounded-xl">
          <AnimatePresence mode="wait">
            {activeTab === 'chat' ? (
              <motion.div key="chat" initial={{ x: direction * 200 }} animate={{ x: 0 }} exit={{ x: direction * -200 }}>
                {messages.map((msg, idx) => (
                  <div key={idx} className="mb-2 p-2 bg-gray-200 rounded-xl">
                    {msg}
                  </div>
                ))}
              </motion.div>
            ) : (
              <motion.div key="participants" initial={{ x: direction * 200 }} animate={{ x: 0 }} exit={{ x: direction * -200 }}>
                {remoteUsers.map((user) => (
                  <div key={user.uid} className="mb-2 p-2 bg-gray-200 rounded-xl">
                    Participant: {user.uid}
                  </div>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        <div className="mt-4 relative">
          <div className="flex items-center bg-white rounded-full px-4 py-2">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              className="flex-1 outline-none"
              placeholder="Type a message..."
            />
            <button onClick={() => setShowPicker(!showPicker)} className="text-2xl">😊</button>
            <button onClick={handleSend} className="ml-2 bg-black text-white px-4 py-1 rounded-full">
              ➤
            </button>
          </div>
          {showPicker && (
            <div className="absolute bottom-16 right-0 z-50" ref={pickerRef}>
              <Picker data={data} onEmojiSelect={addEmoji} />
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
